function advancedTool(id){return ADVANCED_TOOLS.find(t=>t.id===id);}
function advancedScope(){const g=garageState();return g.servers.find(s=>s.id===g.advanced.scope)||g.servers[0];}
function advancedTile(t){const fields=t.groups?.flatMap(x=>x.fields).length;return `<button class="advanced-tool" data-advanced-action="tool" data-value="${t.id}"><span><b>${e(t.title)}</b><p>${e(t.desc)}</p><small>${t.scope?e(t.scope):t.kind==='diagnostic'?'Inspect first · suggested next step':'Open workspace'}${fields?' · '+fields+' controls':''}</small></span>${icon('arrow')}</button>`;}
function advancedResults(section){const terms=garageState().advanced.query.toLowerCase().split(/[^a-z0-9]+/).filter(w=>w&&!['a','an','the','my','is','to','for','how','why','not','working','and','with'].includes(w));const tasks=ADVANCED_TOOLS.filter(t=>(!section||t.section===section)&&terms.every(word=>[t.id,t.title,t.desc,t.section,...(t.groups||[]).flatMap(g=>g.fields.map(f=>f.label))].join(' ').toLowerCase().includes(word)));return tasks.length?tasks.map(advancedTile).join(''):`<div class="garage-empty"><h2>No matching controls.</h2><p>Try “ports”, “weather”, “restore”, or “capture”.</p></div>`;}
function advancedPage(id){const section=ADVANCED_SECTIONS.find(s=>s.id===id),g=garageState(),q=g.advanced.query;return `${garageCrumb(section?.name||'Advanced')}
  <div class="advanced-layout"><aside class="advanced-sidebar"><div class="eyebrow">UNDER THE HOOD</div><a class="advanced-nav-home ${!id?'selected':''}" href="#advanced">${icon('sliders')} Advanced</a><nav aria-label="Advanced sections">${ADVANCED_SECTIONS.map(s=>`<a href="#advanced/${s.id}" data-advanced-action="section" data-value="${s.id}" ${s.id===id?'aria-current="page"':''}>${icon(s.icon)}${s.name}</a>`).join('')}</nav><a class="advanced-help-link" href="#garage">${icon('back')} Back to Garage</a></aside>
  <div class="advanced-workspace"><div class="advanced-page-heading"><span class="eyebrow accent">${section?.group||'ALL THE CONTROLS. A CLEARER WAY IN.'}</span><h1>${e(section?.name||'Under the hood.')}</h1><p>${e(section?.summary||'Build exactly what you want. Understand what went wrong. Get back to driving.')}</p></div>
  <div class="advanced-toolbar"><label class="search">${icon('search')}<input data-advanced-search value="${e(q)}" placeholder="Find a setting or describe the problem…" aria-label="Search all advanced controls"></label><label class="advanced-scope">Server context<select data-advanced-scope>${g.servers.map(s=>`<option value="${s.id}" ${advancedScope().id===s.id?'selected':''}>${e(s.name)}</option>`).join('')}</select></label></div>
  <div class="advanced-demo-label">${icon('info')} Concept workspace · changes, checks, and repairs are simulated.</div>
  ${g.advanced.history.length?`<div class="advanced-last-change"><span><b>${g.advanced.history[0].undone?'Undone':'Last change'}:</b> ${e(g.advanced.history[0].title)}</span><button class="text-button" data-advanced-action="tool" data-value="change-history">Review & undo ${icon('arrow')}</button></div>`:''}
  <div id="advanced-results">${q?`<div class="advanced-tool-list">${advancedResults()}</div>`:section?`<div class="advanced-tool-list">${advancedResults(id)}</div>`:`<div class="advanced-start"><div><span class="eyebrow">SOMETHING NOT WORKING?</span><h2>Start with what you see.</h2><p>You shouldn’t need to know which setting caused it.</p></div><div>${['readiness','stream-health','telemetry'].map(key=>`<button data-advanced-action="tool" data-value="${key}">${e(advancedTool(key).title)} ${icon('arrow')}</button>`).join('')}</div></div><div class="advanced-category-grid">${ADVANCED_SECTIONS.filter(s=>s.id!=='health').map(s=>`<a href="#advanced/${s.id}"><span class="setting-icon">${icon(s.icon)}</span><h2>${s.name}</h2><p>${s.summary}</p><span>${ADVANCED_TOOLS.filter(t=>t.section===s.id).length} tools ${icon('arrow')}</span></a>`).join('')}</div>`}</div>
  <p class="advanced-footnote">${ADVANCED_TOOLS.length} tools mapped from the original app and the new recovery workflows. <a href="ADVANCED-COVERAGE.md" target="_blank">View the capability map ↗</a></p></div></div>`;}
function fieldHTML(f,value){const v=value??f.value;if(f.type==='checkbox')return `<label class="toggle-line"><span>${e(f.label)}</span><input name="${f.key}" type="checkbox" ${v?'checked':''}></label>`;const input=f.type==='select'?`<select name="${f.key}">${f.options.map(o=>`<option ${String(v)===o?'selected':''}>${e(o)}</option>`).join('')}</select>`:['textarea','json'].includes(f.type)?`<textarea name="${f.key}" rows="${f.type==='json'?7:3}" class="${f.type==='json'?'code-input':''}">${e(typeof v==='string'?v:JSON.stringify(v,null,2))}</textarea>`:`<input name="${f.key}" type="${f.type}" value="${f.type==='password'?'':e(v)}" ${f.type==='number'?'min="0" step="any"':''} ${f.type==='password'?'autocomplete="off" placeholder="Demo entry · not retained"':''}>`;return `<label class="field">${e(f.label)}${input}${f.type==='json'?'<small>Ordered entries in JSON. Review the exact values before applying.</small>':''}</label>`;}
function toolValuesKey(t){return t.id+'@'+(t.scope?.startsWith('Selected')?advancedScope().id:'club');}
function instanceGroups(t){const g=garageState(),s=t.id==='new-instance'?{name:'Club '+String(g.servers.length+1).padStart(2,'0'),udp:9600+g.servers.length*4,tcp:9600+g.servers.length*4,http:8081+g.servers.length,plugin:11000+g.servers.length*4,listen:12000+g.servers.length*4}:advancedScope();return [ag('Server identity',af('Server name',s.name)),ag('Game connections',af('UDP port',s.udp,'number'),af('TCP port',s.tcp,'number'),af('HTTP port',s.http,'number')),ag('Telemetry plugin pair',af('Plugin port',s.plugin,'number'),af('Plugin listen port',s.listen,'number'))];}
function toolForm(t){const groups=t.kind==='instance'?instanceGroups(t):t.groups,values=t.kind==='instance'?{}:garageState().advanced.values[toolValuesKey(t)]||{};modal(e(t.title),`<p>${e(t.desc)}</p><div class="advanced-scope-note"><b>${e(t.scope||'Demo settings')}</b><span>${t.scope?.startsWith('Selected')?e(advancedScope().name):'Local preview'}</span></div><form data-advanced-form="settings" data-tool="${t.id}">${groups.map((group,i)=>`<details class="advanced-form-group" ${i===0||groups.length===1?'open':''}><summary>${e(group.label)}<span>${group.fields.length} controls</span></summary><div>${group.fields.map(f=>fieldHTML(f,values[f.key])).join('')}</div></details>`).join('')}${t.preset?'<p class="notice">A private copy leaves existing sessions alone. Updating a shared preset must show all affected setups before applying.</p>':''}<div class="error" role="alert"></div><div class="dialog-actions">${btn('Cancel','close')}<button class="button primary" type="submit">Review changes ${icon('arrow')}</button></div></form>`);}
function diagnostic(t){const server=advancedScope();let rows,log;
  if(['stream-health','recorder-diagnostics'].includes(t.id)){const failed=watchState().sources.find(s=>s.status!=='live');rows=[['Player connection',failed?failed.name+' is not sending a signal. Other cameras remain available.':'All sample players are connected.'],['Recording service','Sample ffmpeg available · 6 buffered segments · last segment 2 seconds ago.'],['Recording link','WHEP is for watching. Recording needs a pullable RTSP, RTMP, SRT, or HLS source.']];log='[sample] player: checking configured source\n[sample] recorder: segments=6, age=2s\n[sample] game presence checked independently';}
  else if(t.id==='telemetry'){rows=[['Server process',server.name+' is responding in this sample.'],['Plugin pair',server.plugin+' → '+server.listen+' · no sample conflict.'],['Position updates','Last sample position held. Verify plugin output and selected track/layout metadata.']];log='[sample] UDP plugin connected\n[sample] drivers=6\n[sample] positions delayed: verify source timestamps';}
  else if(['content-health','system-info'].includes(t.id)){rows=[['Installation','/corsa · sample path, not inspected on disk.'],['Content index',garageState().content.filter(c=>!c.archived).length+' records in the concept library.'],['Map metadata','Layout image, offsets, scale, margin, and AI line are available for the three sample tracks.']];log='[sample] configuration=/corsa/servermanager\n[sample] temporary=/tmp/servermanager\n[sample] engine=AssettoServer · version=design-study';}
  else if(t.id==='logs'){rows=[['Application','No live log is being read. These entries demonstrate the support view.'],['Scope',server.name+' · local demo operations only.']];log=garageState().advanced.history.map(x=>'[demo] '+x.title+' · '+x.scope).join('\n')||'[sample] server ready\n[sample] capture source awaiting signal\n[sample] content index current';}
  else{rows=[['Installation & engine','Sample folder and server binary available.'],['Grid & content','12 requested slots · Rudskogen has 16 pit spaces.'],['Ports & queue',server.name+' selected. Inspect its queue and port assignments before starting.']];log='[sample] install: ready\n[sample] content: ready\n[sample] grid: 12 / 16\n[sample] queued setup: ready';}
  modal(e(t.title),`<div class="diagnostic-summary"><span class="setting-icon">${icon('info')}</span><div><h3>Here’s where to look.</h3><p>Sample diagnosis · ${e(server.name)}</p></div></div>${rows.map(([label,text])=>`<div class="diagnostic-row"><b>${label}</b><p>${e(text)}</p></div>`).join('')}<details class="advanced"><summary>Show the technical evidence</summary><pre class="advanced-code">${e(log)}</pre></details><div class="dialog-actions">${btn('Close','close')}${['stream-health','recorder-diagnostics'].includes(t.id)?garageButton('Open rigs & cameras','advanced-rigs','','primary'):t.id==='telemetry'?`<button class="button primary" data-advanced-action="tool" data-value="instance">Check plugin ports</button>`:t.id==='content-health'?`<button class="button primary" data-advanced-action="tool" data-value="recache">Review index rebuild</button>`:`<button class="button primary" data-advanced-action="export" data-value="support">Export sample report</button>`}</div>`);}
let advancedPending=null;
function reviewAdvanced(t,values,groups){const previous=garageState().advanced.values[toolValuesKey(t)]||{},server=advancedScope();advancedPending={tool:t.id,values,key:toolValuesKey(t),scope:server.id,previous};const rows=groups.flatMap(g=>g.fields).filter(f=>String(values[f.key])!==String(previous[f.key]??f.value));modal('Know what will change.',`<div class="advanced-review-heading"><span class="eyebrow">${e(server.name)} / DEMO PREVIEW</span><h3>${e(t.title)}</h3><p>${e(t.scope||'Local settings')}</p></div>${values.save_scope==='Update shared preset'?'<div class="advanced-impact"><b>Shared preset edit</b><p>Thursday drift club and An evening at Ebisu are sample affected setups. Production must obtain the actual usage list before saving.</p></div>':''}<div class="advanced-diff">${(rows.length?rows:groups.flatMap(g=>g.fields)).map(f=>`<div><b>${e(f.label)}</b><span>${e(f.type==='password'?'Demo value will not be retained':typeof values[f.key]==='boolean'?values[f.key]?'On':'Off':values[f.key])}</span></div>`).join('')}</div><p class="notice">Apply changes to this concept only. No running server, file, account, or recorder is changed.</p><div class="dialog-actions">${btn('Cancel','close')}<button class="button primary" data-advanced-action="apply">${t.id==='custom-session'?'Create custom draft':'Apply to demo'}</button></div>`);}
function validateAdvanced(t,values,groups){for(const f of groups.flatMap(g=>g.fields)){const v=values[f.key];if(f.type==='number'&&(!Number.isFinite(Number(v))||Number(v)<0))return f.label+' must be a non-negative number.';if(f.type==='json'){try{if(!Array.isArray(JSON.parse(v)))return f.label+' must be an array of ordered entries.';}catch{return f.label+' needs valid JSON before it can be reviewed.';}}if(f.type==='url'&&v){try{if(!['http:','https:'].includes(new URL(v).protocol))throw 0;}catch{return f.label+' must use a complete http:// or https:// URL.';}}}
  if(values.new_password!==undefined&&values.confirm_password!==undefined&&values.new_password!==values.confirm_password)return 'The two password entries must match.';
  if(t.kind==='instance'){if(!values.server_name?.trim())return 'Give this server a name.';const peers=garageState().servers.filter(s=>t.id==='new-instance'||s.id!==advancedScope().id);if(peers.some(s=>s.name.toLowerCase()===values.server_name.toLowerCase()))return 'A server already has that name.';if(t.id==='instance'&&state.sessions.some(s=>s.status==='live'&&s.server===advancedScope().name))return 'Stop this server before changing its ports or name.';for(const key of ['udp_port','tcp_port','http_port','plugin_port','plugin_listen_port'])if(!Number.isInteger(Number(values[key]))||Number(values[key])<1||Number(values[key])>65535)return 'Ports must be whole numbers between 1 and 65535.';const tcp=[+values.tcp_port,+values.http_port],udp=[+values.udp_port,+values.plugin_port,+values.plugin_listen_port];if(new Set(tcp).size!==tcp.length||new Set(udp).size!==udp.length||peers.some(s=>tcp.some(p=>[s.tcp,s.http].includes(p))||udp.some(p=>[s.udp,s.plugin,s.listen].includes(p))))return 'A port is already in use. Choose a free TCP/HTTP or UDP/plugin pair.';}
  if(t.id==='custom-session'){if(!values.session_name.trim())return 'Give the custom session a name.';if(+values.grid_size<1||+values.grid_size>tracks[values.track].capacity)return 'The grid must fit this track’s '+tracks[values.track].capacity+' pit spaces.';if(+values.duration_minutes<1)return 'Choose a session duration of at least one minute.';}
  if(t.id==='grid'){const entries=JSON.parse(values.grid_entries);if(!entries.length||entries.some(x=>!x.car||!Number.isInteger(x.count)||x.count<1||!Number.isFinite(x.ballast)||x.ballast<0))return 'Each grid entry needs a car, positive whole count, and non-negative ballast.';}
  return '';
}
function queueEditor(){const server=advancedScope(),adv=garageState().advanced,mode=adv.values['repeat@'+server.id]?.run_mode||'Manual queue',rows=state.sessions.filter(s=>s.server===server.name&&s.status==='planned');modal('The plan for '+e(server.name),`<p>${mode==='Repeat event'?'This server repeats one setup. The manual queue is waiting.':'Move a session up or down. The current drive stays where it is.'}</p>${mode==='Repeat event'?'<div class="advanced-impact">Return to Manual queue in Repeat a session before changing the running order.</div>':rows.map((s,i)=>`<div class="queue-demo-row"><span class="queue-number">${i+1}</span><span><b>${e(s.name)}</b><small>${e(track(s).name)} · ${s.duration} minutes · ${e(s.when)}</small></span><button data-advanced-action="queue-up" data-value="${s.id}" aria-label="Move ${e(s.name)} up" ${i?'':'disabled'}>↑</button><button data-advanced-action="queue-down" data-value="${s.id}" aria-label="Move ${e(s.name)} down" ${i<rows.length-1?'':'disabled'}>↓</button><button data-advanced-action="queue-remove" data-value="${s.id}" aria-label="Remove ${e(s.name)} from plan">×</button></div>`).join('')||'<div class="garage-empty"><h3>The next session is yours to choose.</h3><p>Add one setup or a whole saved group.</p></div>'}<div class="dialog-actions"><button class="button" data-advanced-action="tool" data-value="queue-actions">More queue actions</button>${mode==='Manual queue'?'<button class="button primary" data-advanced-action="queue-add">Add sample session</button>':'<button class="button primary" data-advanced-action="tool" data-value="repeat">Change run mode</button>'}</div>`);}
function rawEditor(){const saved=garageState().advanced.values['raw-config@'+advancedScope().id];modal('See exactly what will run.',`<p>Edit a draft of the generated files. Check it before saving. Custom file editing is a proposed addition to the original render preview.</p><form data-advanced-form="raw"><div class="advanced-scope-note"><b>${e(advancedScope().name)}</b><span>Custom draft · no files written</span></div><label class="field">server_cfg.ini<textarea class="code-input" name="server" rows="9">${e(saved?.server_cfg||`[SERVER]\nNAME=${draft?.name||'Custom club session'}\nTRACK=${draft?.track||'rudskogen'}\nMAX_CLIENTS=${draft?.grid||12}\n\n[PRACTICE]\nNAME=Open practice\nTIME=${draft?.duration||60}\nIS_OPEN=1`)}</textarea></label><label class="field">entry_list.ini<textarea class="code-input" name="entries" rows="7">${e(saved?.entry_list||'[CAR_0]\nMODEL=nissan_silvia_s14\nSKIN=club\nBALLAST=0\nRESTRICTOR=0')}</textarea></label><div class="error" role="alert"></div><p class="notice">The prototype checks basic INI structure only. Production must run the existing renderer, grid checks, and compatibility validation.</p><div class="dialog-actions">${btn('Cancel','close')}<button class="button primary">Check draft</button></div></form>`);}
function repairPreview(t){const cleanup=t.id==='cleanup';modal(cleanup?'Clear the clutter. Keep the driving.':'Refresh what the library knows.',`<p>${cleanup?'Review the exact cleanup targets first.':'A rebuild rescans installed content and refreshes the library index.'}</p><div class="repair-preview">${(cleanup?[['2 failed sample jobs','Clear finished error records'],['48 MB temporary downloads','Discard incomplete sample downloads'],['Recordings, content & database','Keep all of these']]:[['Installed files','Read existing content'],['Library index','Rebuild names, layouts, images and counts'],['Sessions & recordings','Keep all references and media']]).map(([a,b])=>`<div><b>${a}</b><span>${b}</span></div>`).join('')}</div><div class="dialog-actions">${btn('Cancel','close')}<button class="button primary" data-advanced-action="repair" data-value="${t.id}">${cleanup?'Run sample cleanup':'Rebuild sample index'}</button></div><p class="notice">This updates the demo status only. No files are scanned or removed.</p>`);}
function backupPreview(){modal('Choose what to keep.',`<p>A backup should say exactly what is inside it.</p><div class="backup-options">${[['database','Settings & database','Presets, setups, accounts, servers and history.'],['content','Content archive','Installed cars and tracks; separate from settings.'],['media','Recordings & photos','Captured media needs its own explicit backup scope. Proposed extension.']].map(([id,name,desc])=>`<div><b>${name}</b><p>${desc}</p><button class="text-button" data-advanced-action="export" data-value="${id}">Export sample manifest ${icon('arrow')}</button></div>`).join('')}</div><p class="notice">Exports are small JSON demo manifests. They contain no production database, content, recordings, or credentials.</p>`);}
function restorePreview(){modal('Restore deliberately.',`<p>The original database restore is staged and applied on the next application restart.</p><div class="advanced-impact"><b>Sample database restore</b><p>Replaces presets, events, users, and instances. Content and recordings are separate. Keep the previous database available for rollback.</p></div><div class="restore-steps"><span>1. Choose backup</span><span>2. Inspect its scope</span><span>3. Stage for next restart</span></div><div class="dialog-actions">${btn('Cancel','close')}<button class="button primary" data-advanced-action="stage-restore">Stage sample restore</button></div>${garageState().advanced.stagedRestore?'<p class="notice">A sample restore is staged. Cancel it from Recent changes & undo.</p>':''}`);}
function removalPreview(t){const isServer=t.id==='delete-instance',server=advancedScope(),g=garageState();if(isServer){const used=state.sessions.filter(s=>s.server===server.name&&s.status!=='finished'),blocked=g.servers.length<2||used.length;modal('Remove '+e(server.name)+'?',`<p>Keep at least one server. A running or planned session needs a home.</p>${blocked?`<div class="advanced-impact">${g.servers.length<2?'This is your last server.':used.length+' live or planned session(s) still use this server.'} Resolve that before removal.</div>`:'<div class="readiness">Stopped, with no active or planned sessions. This demo server can be removed.</div>'}<div class="dialog-actions">${btn('Keep server','close')}<button class="button" data-advanced-action="remove-server" data-value="${server.id}" ${blocked?'disabled':''}>Remove demo server</button></div>`);return;}
  modal('Inspect before deleting.',`<p>Choose a sample item to inspect its usage. Actual disk deletion belongs behind a usage check and a clear confirmation.</p>${g.content.filter(c=>!c.archived).slice(0,8).map(c=>`<div class="managed-source"><span class="setting-icon">${icon('car')}</span><span><b>${e(c.name)}</b><small>${contentUsage(c).length} session references · ${contentUsage(c).length?'in use':'unused sample item'}</small></span>${garageButton('Open item','advanced-content',c.id,'compact')}</div>`).join('')}<p class="notice">The concept supports reversible library archiving on the item page. It never deletes content from disk.</p>`);
}
function metadataPreview(){const g=garageState();modal('The details behind the preview.',`<p>The content service supplies complete records. These sample fields show where that information belongs.</p><details class="advanced-form-group" open><summary>Cars · specifications & skins</summary><div><p>Power, torque, weight, top speed, acceleration, fuel range, power-to-weight, class, tags, description, and each installed skin.</p><pre class="advanced-code">${e(JSON.stringify({name:g.content.find(c=>c.kind==='cars')?.name,specifications:{power_bhp:'from content metadata',torque_nm:'from content metadata',weight_kg:'from content metadata'},power_curve:'RPM/value pairs',torque_curve:'RPM/value pairs',skins:['club','factory']},null,2))}</pre></div></details><details class="advanced-form-group"><summary>Tracks · layouts & map geometry</summary><div><p>Country, city, tags, length, width, pit spaces, run type, layout key, map dimensions, offsets, margin, and scale.</p><pre class="advanced-code">${e(JSON.stringify({track:'rudskogen',layout:'default',pitboxes:16,map_width:WATCH_MAPS.rudskogen.width,map_height:WATCH_MAPS.rudskogen.height},null,2))}</pre></div></details><details class="advanced-form-group"><summary>Weather · presets & graphics keys</summary><div><p>Preview, name and graphics key. Temperature, wind, and CSP date/time live in ordered weather panels.</p></div></details><div class="dialog-actions">${btn('Close','close')}${linkBtn('Open content library','library','primary')}</div>`);}
function changeHistory(){const h=garageState().advanced.history;modal('A clear way back.',`<p>Recent local concept changes. Undo is available for the most recent reversible change.</p>${h.length?h.map((x,i)=>`<div class="change-row"><span class="setting-icon">${icon('check')}</span><span><b>${e(x.title)}</b><small>${e(x.scope)} · ${x.undone?'undone':'applied to demo'}</small></span>${i===0&&!x.undone&&x.undo?'<button class="button compact" data-advanced-action="undo">Undo</button>':''}</div>`).join(''):'<div class="garage-empty"><h3>No changes yet.</h3><p>Reviewed settings and repairs will leave a trail here.</p></div>'}`);}
function logAdvanced(title,scope,undo){garageState().advanced.history.unshift({title,scope,undo});remember();}
function openAdvanced(id){let t=advancedTool(id);if(id==='queue-actions')t={id,section:'automation',title:'Queue actions',desc:'Add a complete group, skip the active event, or clear finished items.',scope:'Selected server',groups:[ag('Queue action',af('Action','Add group','select',['Add group','Skip current event','Clear completed','Clear pending plan']),af('Group or setup','Thursday favourites'))]};if(!t)return;
  if(t.kind==='diagnostic')return diagnostic(t);
  if(t.kind==='instance'||t.groups)return toolForm(t);
  if(t.kind==='link'){close();go(t.route);return;}
  if(t.kind==='sources'){close();go('rigs');return;}
  if(t.kind==='import')return importContent();
  if(t.kind==='queue')return queueEditor();
  if(t.kind==='raw')return rawEditor();
  if(t.kind==='repair')return repairPreview(t);
  if(t.kind==='backup')return backupPreview();
  if(t.kind==='restore')return restorePreview();
  if(t.kind==='remove')return removalPreview(t);
  if(t.kind==='metadata')return metadataPreview();
  if(t.kind==='history')return changeHistory();
}
function applyAdvanced(){const p=advancedPending;if(!p)return;const g=garageState(),t=advancedTool(p.tool)||{id:p.tool,title:'Queue actions',scope:'Selected server'},v=p.values;const undo={kind:'settings',key:p.key,previous:p.previous};
  if(t.kind==='instance'){const selected=g.servers.find(s=>s.id===p.scope);if(t.id==='instance'&&state.sessions.some(s=>s.status==='live'&&s.server===selected?.name)){close();toast('This server is running. Stop it before changing ports.');return;}undo.servers=g.servers.map(s=>({...s}));const old=g.servers.find(s=>s.id===p.scope),entry={id:t.id==='new-instance'?'server-'+(++g.sequence):p.scope,name:v.server_name,udp:+v.udp_port,tcp:+v.tcp_port,http:+v.http_port,plugin:+v.plugin_port,listen:+v.plugin_listen_port};if(t.id==='new-instance')g.servers.push(entry);else{state.sessions.filter(s=>s.server===old.name).forEach(s=>s.server=entry.name);undo.previousName=old.name;undo.newName=entry.name;Object.assign(old,entry);}g.advanced.scope=entry.id;}
  // ponytail: settings are a local reviewable draft; production adapters belong with the existing API models.
  const safeValues={...v};Object.keys(safeValues).filter(k=>k.includes('password')).forEach(k=>safeValues[k]='');g.advanced.values[p.key]=safeValues;
  logAdvanced(t.title,t.scope||'Local draft',t.id==='custom-session'?null:undo);advancedPending=null;close();
  if(t.id==='custom-session'){makeDraft(v.driving_type);Object.assign(draft,{name:v.session_name,track:v.track,cars:v.car_class_preset,grid:+v.grid_size,duration:+v.duration_minutes,rules:v.difficulty_preset,weather:v.time_and_weather_preset,customConfig:{...safeValues}});remember();go('build');toast('Custom draft ready. Review it before starting.');return;}
  render();toast('Applied to the concept. Review or undo it in System & logs.');
}
document.addEventListener('submit',event=>{const form=event.target.closest('[data-advanced-form]');if(!form)return;event.preventDefault();const data=new FormData(form);
  if(form.dataset.advancedForm==='raw'){const cfg=String(data.get('server')),entries=String(data.get('entries')),valid=text=>text.split('\n').every(line=>!line.trim()||/^\s*[;#]/.test(line)||/^\s*\[[^\]]+\]\s*$/.test(line)||/^\s*[^=\s]+\s*=.*$/.test(line));if(!valid(cfg)||!valid(entries)||!cfg.includes('[SERVER]')||!entries.includes('[CAR_0]')){form.querySelector('.error').textContent='Use [SERVER] and [CAR_0] sections with KEY=value lines.';return;}const t=advancedTool('raw-config');return reviewAdvanced(t,{server_cfg:cfg,entry_list:entries},[ag('Configuration',af('Server cfg',cfg,'textarea'),af('Entry list',entries,'textarea'))]);}
  const t=advancedTool(form.dataset.tool)||{id:'queue-actions',title:'Queue actions',scope:'Selected server',groups:[ag('Action',af('Action',data.get('action')),af('Group or setup',data.get('group_or_setup')))]};const groups=t.kind==='instance'?instanceGroups(t):t.groups,values={};for(const f of groups.flatMap(g=>g.fields))values[f.key]=f.type==='checkbox'?data.get(f.key)==='on':String(data.get(f.key)||'').trim();const error=validateAdvanced(t,values,groups);if(error){form.querySelector('.error').textContent=error;return;}reviewAdvanced(t,values,groups);
});
document.addEventListener('click',event=>{const el=event.target.closest('[data-advanced-action]');if(!el)return;const a=el.dataset.advancedAction,v=el.dataset.value,g=garageState(),adv=g.advanced;
  if(a==='section'){event.preventDefault();adv.query='';remember();go('advanced/'+v);return;}
  if(a==='tool')return openAdvanced(v);
  if(a==='apply')return applyAdvanced();
  if(a==='repair'){const prev=adv.cleaned;adv.cleaned=true;if(v==='recache')g.jobs.unshift({name:'Content index',detail:'Sample rescan complete · no files changed',status:'Current'});logAdvanced(v==='cleanup'?'Sample temporary-file cleanup':'Sample content index rebuilt','No content or recordings removed',{kind:'cleanup',previous:prev});close();render();toast(v==='cleanup'?'Sample cleanup complete. Recordings and content were kept.':'Sample content index refreshed.');return;}
  if(a==='stage-restore'){const prev=adv.stagedRestore;adv.stagedRestore=true;logAdvanced('Database restore staged','Sample · next restart',{kind:'restore',previous:prev});close();render();toast('Sample restore staged. Undo from Recent changes.');return;}
  if(a==='remove-server'){const server=g.servers.find(s=>s.id===v);if(!server||g.servers.length<2||state.sessions.some(s=>s.server===server.name&&s.status!=='finished'))return;logAdvanced('Removed '+server.name,'Demo servers',{kind:'server-remove',server:{...server}});g.servers=g.servers.filter(s=>s.id!==v);adv.scope=g.servers[0].id;close();render();return;}
  if(a==='queue-add'){const server=advancedScope();if(adv.values['repeat@'+server.id]?.run_mode==='Repeat event')return;const id='queue-'+(++g.sequence);state.sessions.push({...initialState().sessions[1],id,server:server.name,name:'Next up · '+g.sequence,date:'2026-09-12T19:00',when:'19:00'});remember();return queueEditor();}
  if(['queue-up','queue-down','queue-remove'].includes(a)){const server=advancedScope();if(adv.values['repeat@'+server.id]?.run_mode==='Repeat event')return;const s=findSession(v);if(!s||s.status!=='planned'||s.server!==server.name)return;if(a==='queue-remove')state.sessions=state.sessions.filter(x=>x.id!==v);else{const indices=state.sessions.map((x,i)=>x.status==='planned'&&x.server===server.name?i:-1).filter(i=>i>=0),index=indices.indexOf(state.sessions.indexOf(s)),other=indices[index+(a==='queue-up'?-1:1)];if(other!==undefined){const here=state.sessions.indexOf(s);[state.sessions[here],state.sessions[other]]=[state.sessions[other],state.sessions[here]];}}remember();return queueEditor();}
  if(a==='undo'){const h=adv.history[0],u=h?.undo;if(!u||h.undone)return;if(u.servers&&g.servers.some(current=>{const previous=u.servers.find(s=>s.id===current.id),changed=!previous||JSON.stringify(previous)!==JSON.stringify(current);return changed&&state.sessions.some(s=>s.server===current.name&&(s.status==='live'||(!previous&&s.status==='planned')));})){toast('A session now uses this server. Stop it or move its plan before undoing this change.');return;}if(u.kind==='settings'){adv.values[u.key]=u.previous;if(u.servers){g.servers=u.servers;if(u.previousName)state.sessions.filter(s=>s.server===u.newName).forEach(s=>s.server=u.previousName);adv.scope=g.servers[0].id;}}if(u.kind==='cleanup')adv.cleaned=u.previous;if(u.kind==='restore')adv.stagedRestore=u.previous;if(u.kind==='server-remove')g.servers.push(u.server);h.undone=true;remember();return changeHistory();}
  if(a==='export'){const payload={kind:v,prototype:true,notice:'Sample manifest only. No production data or credentials.',scope:v==='database'?'Database/settings':v==='media'?'Recordings, separately scoped':v==='content'?'Content archive':'Support information',sample_items:v==='content'?g.content.filter(c=>!c.archived).map(c=>c.name):v==='media'?watchState().captures.map(c=>c.kind):[]};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='pitlane-demo-'+v+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo manifest exported.');}
});
document.addEventListener('input',event=>{if(event.target.hasAttribute('data-advanced-search')){garageState().advanced.query=event.target.value;const query=event.target.value.trim();if(query)document.querySelector('#advanced-results').innerHTML=`<div class="advanced-tool-list">${advancedResults()}</div>`;else{const [,id]=location.hash.slice(1).split('/');document.querySelector('#advanced-results').innerHTML=`<div class="advanced-tool-list">${advancedResults(id)}</div>`;}remember();}});
document.addEventListener('change',event=>{if(event.target.hasAttribute('data-advanced-scope')){garageState().advanced.scope=event.target.value;remember();render();}});
document.addEventListener('click',event=>{const el=event.target.closest('[data-garage-action]');if(el?.dataset.garageAction==='advanced-rigs'){close();go('rigs');}if(el?.dataset.garageAction==='advanced-content'){close();go('content/'+el.dataset.value);}});
